INSERT INTO `glpi_itilfollowups` VALUES
(1,'Ticket',1,'2024-05-02 14:03:27',17,17,'&#60;p&#62;Un technicien a vérifié le clavier, celui fonctionne correctement.&#60;/p&#62;\r\n&#60;p&#62;Le mot de passe va être réinitialisé et nous rappelons les bonnes pratiques de l\'Anssi .&#60;/p&#62;',0,1,'2024-05-02 14:04:16','2024-05-02 14:03:27',4,0,0),
(2,'Ticket',2,'2024-05-02 14:18:43',17,0,'&#60;p&#62;Un mail de prise de contact a été envoyé à Ocito&#60;/p&#62;',0,1,'2024-05-02 14:18:43','2024-05-02 14:18:43',4,0,0),
(3,'Ticket',3,'2024-05-02 14:23:03',17,0,'&#60;p&#62;indication par téléphone;&#60;/p&#62;\r\n&#60;p&#62;- débrancher le cable réseau éthernet&#60;/p&#62;\r\n&#60;p&#62;- ne pas éteindre l\'ordinateur&#60;/p&#62;\r\n&#60;p&#62;- attendre l\'arrivée de l\'assistance sur place&#60;/p&#62;',0,3,'2024-05-02 14:23:03','2024-05-02 14:23:03',4,0,0),
(4,'Ticket',7,'2024-05-02 14:34:19',17,0,'&#60;p&#62;Information à Edouard que la mise à jour des serveurs est de la compétence des adminsys. Finalement, il désire simplement un accès aux logs, accès autorisé par la charte.&#60;/p&#62;',0,1,'2024-05-02 14:34:19','2024-05-02 14:34:19',4,0,0),
(5,'Ticket',8,'2024-05-02 14:36:59',17,0,'&#60;p&#62;Etant donné la réaction de son collaborateur Steeve, un mail commun est envoyé à Raphaël et son collaborateur.&#60;/p&#62;',0,1,'2024-05-02 14:36:59','2024-05-02 14:36:59',4,0,0);
