INSERT INTO `glpi_tickets` VALUES
(1,0,'problème de mot de passe ordinateur','2024-05-02 08:30:00',NULL,NULL,'2024-05-02 14:01:38','2024-05-02 14:04:16',17,2,17,3,'&#60;p&#62;Charly, du service comptabilité, n\'arrive pas à se connecter sur son poste de travail. Un message d\'erreur \"mot de passe invalide\" s\'affiche.&#60;/p&#62;',5,4,5,0,1,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,19898,0,0,0,0,'2024-05-02 14:01:38'),
(2,0,'raccordement VPN OCITO ','2024-05-02 13:00:00',NULL,NULL,'2024-05-02 14:16:51','2024-05-02 14:19:17',17,2,17,4,'&#60;p&#62;Elise, de l\'équipe commerciale, demande au service de prendre contact avec le partenaire Ocito pour la mise en place d\'un VPN Ipsec&#60;/p&#62;',3,3,3,0,1,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,4611,0,0,0,0,'2024-05-02 14:16:51'),
(3,0,'problème d\'accès à la boite mail et suite bureautique suite ouverture pj mail','2024-05-02 15:30:00',NULL,NULL,'2024-05-02 14:22:06','2024-05-02 14:24:09',17,2,17,3,'&#60;p&#62;Samuel a reçu par mail un devis d\'un prestataire externe. Après ouverture de la pièce jointe, son mail ne fonctionne plus ainsi que la suite bureautique. Il est totalement bloqué.&#60;/p&#62;',5,3,4,0,1,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,1,0,0,0,0,'2024-05-02 14:22:06'),
(4,0,'i-tunes sur le portable','2024-05-02 13:45:00',NULL,NULL,'2024-05-02 14:26:14','2024-05-02 14:26:14',17,2,17,4,'&#60;p&#62;Guillaume, le PDG, désire de l\'aide pour installer i-tunes sur son ordi portable.&#60;/p&#62;\n&#60;p&#62;Il faut lui rappeler par mail en mettant les formes  la charte informatique du SI avec les autres services et validée par la Direction Générale&#60;/p&#62;',5,1,2,0,1,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,2474,0,0,0,0,'2024-05-02 14:26:14'),
(5,0,'commande de disques durs','2024-05-02 14:10:00',NULL,NULL,'2024-05-02 14:29:11','2024-05-02 14:30:12',17,2,17,4,'&#60;p&#62;Karim de l\'équipe Hardware a besoin de disques durs: 10 disques durs de 4To et5 de 8 To de marque Toshiba&#60;/p&#62;',3,3,3,0,2,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,1151,0,0,0,0,'2024-05-02 14:29:11'),
(6,0,'nouveaux téléphones','2024-05-02 11:45:00',NULL,NULL,'2024-05-02 14:32:10','2024-05-02 14:32:10',17,2,17,4,'&#60;p&#62;Philippe désire savoir à quand les nouveaux téléphones seront distribués.&#60;/p&#62;\n&#60;p&#62;Les nouveaux téléphones arrivent par lot, les lots reçu ont déjà été distribués.&#60;/p&#62;',1,1,1,0,1,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,10030,0,0,0,0,'2024-05-02 14:32:10'),
(7,0,'demande d\'accès compte root du serveur web pour déboguer un problème d\'affichage','2024-05-02 11:30:00',NULL,NULL,'2024-05-02 14:33:38','2024-05-02 14:34:19',17,2,17,3,'&#60;p&#62;Edouard est développeur web et travaille sur le projet de refonte du site et désire accèder au compte root du serveur pour déboguer un problème d\'affichage&#60;/p&#62;',3,3,3,0,1,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,11018,0,0,0,0,'2024-05-02 14:33:38'),
(8,0,'suppression accès Zefyr par Raphaël, rds service comptable','2024-05-02 09:00:00',NULL,NULL,'2024-05-02 14:36:14','2024-05-02 14:36:59',17,2,17,2,'&#60;p&#62;Raphaël nous informe avoir supprimé les accès utilisateurs de son équipe au logiciel Zefyr pour insuffisance de maîtrise. Etant donné la réaction de son collaborateur Steeve, un mail commun est envoyé à Raphaël et son collaborateur.&#60;/p&#62;',3,3,3,0,2,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,20174,0,0,0,0,'2024-05-02 14:36:14'),
(9,0,'code alerte climatisation','2024-05-02 15:30:00',NULL,NULL,'2024-05-02 14:39:01','2024-05-02 14:39:01',17,2,17,4,'&#60;p&#62;Marina nous informe que le code d\'alerte E458 s\'est affiché sur la climatisation n°3. Il faut l\'informer que c\'est le service maintenance qui est en charge de ce genre de problème. On la remercie de son signalement et on transmet le message au service concerné.&#60;/p&#62;',3,3,3,0,1,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,1,0,0,0,0,'2024-05-02 14:39:01'),
(10,0,'logiciel Zefyr','2024-05-02 09:40:00',NULL,NULL,'2024-05-02 14:40:44','2024-05-02 14:45:51',17,2,17,1,'&#60;p&#62;Steeve n\'a plus accès à Zefyr et veut en discuter. Il a tenté d\'appeler le service en vain et a laissé des messages. Une réponse personnelle est effectuée auprès de Steeve pour expliquer la situation.&#60;/p&#62;',3,3,3,0,1,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,18044,0,0,0,0,'2024-05-02 14:40:44'),
(11,0,'logiciel Zefyr','2024-05-02 13:30:00',NULL,NULL,'2024-05-02 14:44:30','2024-05-02 14:45:05',17,2,17,3,'&#60;p&#62;Steeve de la compta a un besoin urgent de ce logiciel. Il demande avec insistance le rétablissement de ses droits d\'accès retirés par son chef de service&#60;/p&#62;',3,3,3,0,1,1,0,0,0,NULL,NULL,NULL,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,0,4470,0,0,0,0,'2024-05-02 14:44:30');
